import smtplib
import ssl

from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
from typing import Union

from taf.rfrl.csv4all.resources.utilities.decorators import test_logger


class Notifications:

    def __init__(self, email_recipients):
        self.email_recipients = self.email_validation(email_recipients)

    @staticmethod
    def _send(email):
        """
        Sends email from source address to destination addresses

        :param Email email:
        """
        server = smtplib.SMTP('mailrelay.int.nokia.com', 25)
        try:
            context = ssl.SSLContext(ssl.PROTOCOL_TLSv1_2)
            context.set_ciphers('DEFAULT@SECLEVEL=1')
            server.starttls(context=context)
            server.sendmail(email.sender, email.to, email.get_raw_message())
            test_logger(f"Sent email to {', '.join(email.to)}", console=False)
        except Exception as e:
            test_logger(e, "DEBUG")
        finally:
            server.quit()

    def send_email(self, body: str, subject: str, to: list = None, text_type: str = "html") -> None:
        recipients = self.email_recipients if not to else self.email_validation(to)
        if recipients:
            email = Email(to=recipients, subject=subject, body=body,
                          body_text_subtype=text_type)
            self._send(email)
        else:
            test_logger("No valid email recipients was provided", "DEBUG")

    @staticmethod
    def email_validation(emails: Union[str, list]) -> list:
        if not emails:
            return []
        allowed_domains = ["@nokia.com", "@internal.nsn.com"]
        emails = set(emails.split(",")) if isinstance(emails, str) else set(emails)
        valid_emails = {mail.lstrip() for mail in emails if any(domain in mail for domain in allowed_domains)}
        invalid_emails = emails - valid_emails
        if invalid_emails:
            test_logger(f"Emails not supported: {','.join(invalid_emails)}")
        return list(valid_emails)


class Email(Notifications):

    def __init__(self, to: list = None, subject: str = None, body: str = None, attachments: list = None,
                 body_text_subtype: str = 'html'):
        """
        |space|
        :param str subject: email subject line
        :param str body: text of the email
        :param str body_text_subtype: MIME sub content type
        :param list(Attachment) attachments: list of attachments to attach
        """
        super().__init__(to)
        self.sender = 'notifications.ta@nokia.com'
        self.to = to if to else []
        self.subject = subject
        self.attachments = attachments if attachments else []
        self.body = body
        self.body_text_subtype = body_text_subtype

    def __repr__(self):
        return self.get_raw_message()

    def get_raw_message(self):
        """
        Generates a message which is ready to be sent by an email server.

        :return: message
        :type: str
        """
        message = MIMEMultipart()
        message['From'] = self.sender
        message['To'] = ','.join(self.to)
        message['Subject'] = self.subject
        message.attach(MIMEText(self.body, self.body_text_subtype))
        for attachment in self.attachments:
            message.attach(attachment.get_raw_text())
        return message.as_string()
